/**
 * Journey 2: importing real screenshots (PNG files generated by the test at
 * the iPhone 6.3″ size) through the inspector's file picker and by dropping
 * files onto a device on the stage, in the base language and as an Arabic
 * localized screenshot.
 */
import { expect, test } from './fixtures';
import {
  closeColor,
  dropFiles,
  editorState,
  elementOnStage,
  expectToast,
  missingShotsShown,
  openDemo,
  openProject,
  pickFiles,
  screenshot,
  showSlide,
  stage,
  stagePixel,
  type Rgb,
} from './helpers';

const GREEN: Rgb = [30, 160, 90];
const RED: Rgb = [210, 60, 60];
const BLUE: Rgb = [40, 90, 220];
const GOLD: Rgb = [230, 180, 40];
const PINK: Rgb = [240, 110, 170];
const TEAL: Rgb = [20, 170, 170];
const VIOLET: Rgb = [120, 70, 200];

test('import screenshots with the inspector picker and by drag and drop', async ({ page }) => {
  await openDemo(page, { template: 'sunset-boulevard' });
  const inspector = page.getByRole('complementary', { name: 'Inspector' });
  const missingAtStart = await missingShotsShown(page);
  expect(missingAtStart, 'every device of the template shows a mock screen').toBeGreaterThanOrEqual(5);

  // 1. Inspector: slide 1's screenshot row opens its device, "Choose…" opens the picker.
  await inspector.getByRole('listbox', { name: 'iPhone screenshots by language' }).getByRole('option', { name: /English/ }).click();
  await expect(inspector.getByText('No screenshot')).toBeVisible();
  await pickFiles(page, () => inspector.getByRole('button', { name: 'Choose…' }).click(), screenshot('home.png', GREEN));
  await expectToast(page, 'Screenshot added');

  let project = await openProject(page);
  const first = project.slides[0].shots.iphone?.main?.['en-US'];
  expect(first, 'slide 1 holds the picked screenshot in the base language').toMatch(/^[0-9a-f]{64}\.png$/);
  expect(project.assets[first!]).toMatchObject({ name: 'home.png', width: 1206, height: 2622 });
  await expect(inspector.getByText('home.png')).toBeVisible();
  await expect(inspector.getByText('1206 × 2622')).toBeVisible();
  await expect.poll(() => missingShotsShown(page)).toBe(missingAtStart - 1);

  // The device on the canvas now shows the image (its screen centre is the screenshot's colour).
  const device1 = await elementOnStage(page, 0, { kind: 'device' });
  await expect.poll(async () => closeColor(await stagePixel(page, 0, device1), GREEN), { message: 'slide 1 shows the green screenshot' }).toBe(true);
  const decoded = await page.evaluate(async () => {
    const url = '/src/runtime/index.ts';
    const { getImageCache } = (await import(/* @vite-ignore */ url)) as typeof import('../src/runtime/index.ts');
    return getImageCache().memoryBytes();
  });
  expect(decoded, 'a downscaled preview is decoded, not the full image').toBeGreaterThan(0);
  expect(decoded).toBeLessThanOrEqual(1400 * 1400 * 4);

  // 2. Drag and drop one file onto slide 3's device.
  await showSlide(page, 2);
  const device3 = await elementOnStage(page, 2, { kind: 'device' });
  const slide3 = stage(page).getByRole('group', { name: 'Slide 3 of 5' }).locator('[data-slide-box]');
  await dropFiles(page, slide3, [screenshot('map.png', RED, { alpha: true })], device3);
  await expectToast(page, 'Screenshot added');
  await expect.poll(() => missingShotsShown(page)).toBe(missingAtStart - 2);
  project = await openProject(page);
  expect(project.slides[2].shots.iphone?.main?.['en-US']).toMatch(/^[0-9a-f]{64}\.png$/);
  await expect.poll(async () => closeColor(await stagePixel(page, 2, device3), RED), { message: 'slide 3 shows the red screenshot' }).toBe(true);

  // 3. Two files dropped on slide 4: the first lands there, the second fills slide 5.
  await showSlide(page, 3);
  const device4 = await elementOnStage(page, 3, { kind: 'device' });
  const slide4 = stage(page).getByRole('group', { name: 'Slide 4 of 5' }).locator('[data-slide-box]');
  await dropFiles(page, slide4, [screenshot('sunset.png', BLUE), screenshot('offline.png', GOLD)], device4);
  await expectToast(page, '2 screenshots added');
  await expect.poll(() => missingShotsShown(page)).toBe(missingAtStart - 4);
  project = await openProject(page);
  const names = project.slides.map((s) => {
    const id = s.shots.iphone?.main?.['en-US'];
    return id ? project.assets[id]?.name : null;
  });
  expect(names).toEqual(['home.png', null, 'map.png', 'sunset.png', 'offline.png']);
  expect(new Set(Object.keys(project.assets)).size, 'four different images, four assets').toBe(4);

  // 4. The status bar leads to each device still showing a mock screen (slide 2 has two).
  const status = page.getByRole('contentinfo');
  for (const [i, color] of ([PINK, TEAL] as const).entries()) {
    const left = missingAtStart - 4 - i;
    await status.getByRole('button', { name: left === 1 ? '1 missing screenshot' : `${left} missing screenshots` }).click();
    await expect(inspector.getByText('No screenshot')).toBeVisible();
    await pickFiles(page, () => inspector.getByRole('button', { name: 'Choose…' }).click(), screenshot(`friends-${i + 1}.png`, color));
    await expectToast(page, 'Screenshot added');
  }
  await expect(status).toContainText('All screenshots added');
  project = await openProject(page);
  expect(Object.keys(project.slides[1].shots.iphone ?? {}).sort(), 'both devices of slide 2').toEqual(['main', 'second']);

  // 5. Arabic: the base screenshot is the fallback; a picked file becomes the Arabic one.
  await page.getByRole('button', { name: /^Preview language:/ }).click();
  await page.getByRole('menuitemradio', { name: /Arabic/ }).click();
  await expect(page.getByRole('button', { name: 'Preview language: Arabic' })).toBeVisible();
  await expect(status, 'Arabic falls back to the English screenshots').toContainText('All screenshots added');
  await showSlide(page, 0);
  await inspector.getByRole('listbox', { name: 'iPhone screenshots by language' }).getByRole('option', { name: /Arabic/ }).click();
  await expect(inspector.getByText('Using English (US) screenshot — add one for Arabic')).toBeVisible();
  await pickFiles(page, () => inspector.getByRole('button', { name: 'Add Arabic…' }).click(), screenshot('home-ar.png', VIOLET, { width: 1320, height: 2868 }));
  await expectToast(page, 'Screenshot added');
  const state = await editorState(page);
  const shots = state!.project.slides[0].shots.iphone?.main;
  expect(shots?.['en-US']).toBe(first);
  expect(shots?.['ar-SA']).toMatch(/^[0-9a-f]{64}\.png$/);
  expect(shots?.['ar-SA']).not.toBe(first);
  expect(state!.project.assets[shots!['ar-SA']]).toMatchObject({ name: 'home-ar.png', width: 1320, height: 2868 });
  await expect
    .poll(async () => closeColor(await stagePixel(page, 0, await elementOnStage(page, 0, { kind: 'device' })), VIOLET), { message: 'slide 1 shows the Arabic screenshot' })
    .toBe(true);
});
